(138, 1, 'БАДы|Возбудители', '&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;БОЛЕЕ ПОДРОБНУЮ ИНФОРМАЦИЮ ПО АССОРТИМЕНТУ И НАЛИЧИЮ ТОВАРОВ ДАННОЙ КАТЕГОРИИ, УТОЧНЯЙТЕ У КОНСУЛЬТАНТА.&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
