(307, 1, 'SEX игрушки', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(307, 2, 'dfghjlkjhg', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(191, 1, 'Реалистичные', '&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Совсем как настоящий, только еще лучше, потому, что с вибрацией!&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Будет доставлять вам удовольствие сколько будет нужно Вам, и не устанет никогда!&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Большой или маленький, с мошонокй или без, выбирать Вам! Он всегд будет верен!&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(193, 1, 'С ротацией', '&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Массажеры, которые направлены на активную стимуляцию вагинальных мышц.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Он дотянется до всех укромных мест, которые не сможет ласкать половой член ( в связи со своей физиологией).&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Ни одна женщина не останется равнодушной, перед такими массажерами.&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(299, 1, 'Вибраторы для пары', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(299, 2, 'oihliut', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(300, 1, 'Многорежимные ', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(300, 2, 'iuhfohr', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(301, 1, 'Вакуумно-волновые', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(301, 2, 'ijpogujfiugv', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(71, 1, 'Вибраторы', '&lt;p class=&quot;MsoNormal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-size: 12pt; line-height: 115%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;Вибратор&lt;/span&gt;&lt;span style=&quot;font-size: 12pt; line-height: 115%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;nbsp;— электромеханическое изделие,\r\nпредназначенное для&lt;span class=&quot;apple-converted-space&quot;&gt;&amp;nbsp;вагинального и анального массажа&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 12pt; line-height: 115%;&quot;&gt;&lt;span style=&quot;background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;&lt;span style=&quot;font-size: 12pt; line-height: 115%;&quot;&gt;&lt;span style=&quot;background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Всю серость будней, плохое настроение и просто нехватку ласки, Вам поможет избежать вибромассажер, который всегда готов ласкать Вас и удивлять новыми ощущениями. В нашем магазине представленно огромное множество вариантов для релаксирования соло или вместе с партнером! Преобретите &quot;друга&quot;, который всегда будет Вам верен!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(71, 2, 'sdfgh', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(77, 2, 'sgfhj', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', '');
INSERT INTO `oc_category_description` (`category_id`, `language_id`, `name`, `description`, `meta_title`, `meta_h1`, `meta_description`, `meta_keyword`) VALUES
(77, 1, 'Массажные масла', '&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: 18pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Нет ничего желаннее прикосновений любимых рук! Для того чтобы научиться\r\nделать эротический массаж, не нужно быть дипломированным массажистом. Здесь нет\r\nникаких запретов и жестких правил, кроме одного — получить взаимное\r\nудовольствие. Мы расскажем об универсальных приемах такого массажа.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Поднимись над суетой&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;1. Основное правило — забудьте о времени. Забудьте обо\r\nвсем, что не касается этого конкретного момента, что не относится к\r\n&quot;здесь&quot; и &quot;сейчас&quot;. Никакого негатива — иначе ваши руки\r\nмгновенно передадут его любимому человеку, и изысканное удовольствие\r\nпревратится в изощренную пытку. Позаботьтесь о комфортной обстановке —\r\nприветствуется приглушенный свет и, по желанию, негромкая музыка как фон.\r\nОтлично подойдет музыка для медитации.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;2. Позаботьтесь о комфортной температуре в помещении,\r\nчтобы она была не ниже 24—25 градусов. &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;3. Массажное масло выбирайте без резкого запаха.\r\nВозбуждающими считаются масла иланг-иланга, пачули, сандала. Однако если вы не\r\nуверены, что этот аромат понравится, выберите что-нибудь нейтральное —\r\nнапример, аромат клубники, персика, ванили.Опустите емкость с маслом в горячую\r\nводу на несколько минут, чтобы оно согрелось до температуры тела, а когда\r\nбудете его наносить — не экономьте.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;4. Разговоры не приветствуются — пусть за вас говорят\r\nприкосновения.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;5. Приступив к массажу, не допускайте пауз, даже\r\nнезначительных. В этом состоит секрет техники так называемого обволакивающего\r\nмассажа. &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;6. В эротическом массаже в принципе используются те же\r\nприемы, что и в обычном: поглаживания, растирания, разминания, вибрации, только\r\nвсе движения выполняются плавно и нежно. Никакой грубости или применения силы —\r\nразве что ваш партнер сам не попросит об этом. Движения должны быть ритмичными:\r\nчтобы понять, какой ритм правильный, следите за реакцией.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;7. Чем легче прикосновения, тем острее реакция нервных\r\nокончаний. Особенно чувствительна к невесомым поглаживаниям кожа внутренней\r\nповерхности бедер и рук, затылка, а также кожа под коленями и в области\r\nгениталий. Ритмичное прикосновение раскрытых ладоней, когда одна рука сменяет\r\nдругую, создает ощущение прикосновения множества рук. Особенно возбуждающе это\r\nдействует при массаже рук и ступней. Отличие эротического массажа от\r\nклассического еще и в том, что его можно выполнять на передней поверхности\r\nтела, включая живот и половые органы.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;8. Такой массаж может быть прелюдией к сексу, но это\r\nвовсе необязательно. &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;В этот момент близости Вам не обойтись без хорошего\r\nмассажного масла.&lt;/span&gt;&lt;span style=&quot;color: rgb(34, 34, 34); font-family: Arial, sans-serif;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(143, 1, 'Помпы', '&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Вакуумная помпа для\r\nмужчин на данный момент является эффективным средством для увеличения мужского\r\nполового органа и улучшения его работы. Производители гарантируют быстрый\r\nэффект и стойкий результат. Различают электрические и ручные вакуумные помпы.\r\nРучной вариант — это цилиндр диаметром 7 см и длиной около 20 см. К нему\r\nприкрепляется ручной насос, который откачивает воздух из цилиндрической\r\nемкости. Такая помпа в основном выполнена из пластика акрилита. А вот вакуум в\r\nэлектрических приборах образуется при помощи электронасоса, который равномерно\r\nоткачивает воздух. Некоторые модели оснащены специальной кнопкой, регулирующей\r\nинтенсивность создания вакуума в цилиндре. Итак, действие помпы основывается на\r\nсоздании вакуума внутри прибора, в котором находится половой член. В результате\r\nпонижения и повышения давления активизируется кровообращение в члене, благодаря\r\nчему он становится длиннее и толще, чем при обычной эрекции.&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom:0cm;margin-bottom:.0001pt;line-height:\r\nnormal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Вакуумный тренажер для\r\nженщин не столь распространен, как мужской. Но все же секс-индустрия предлагает\r\nпомпы и для женщин. Давайте же разберемся в том, какие помпы существуют,\r\nпостараемся выявить особенности и пользу применения.&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;mso-margin-bottom-alt:auto;line-height:normal;\r\nmso-outline-level:2&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Помпа для груди и сосков&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Такой тренажер\r\nпризнается однозначно полезным при недостаточном тонусе кожи груди и плоских\r\nсосках. Его применение позволяет добиться значительного эффекта: грудь\r\nстановится более упругой, кожа подтягивается, а соски становятся выпуклыми и\r\nлегко эрегируют при прикосновении. Грудь приобретает высокую чувствительность и\r\nкрасивую форму.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;mso-margin-bottom-alt:auto;line-height:normal;\r\nmso-outline-level:2&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Помпа для половых губ и клитора&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Изначально помпа\r\nсоздавалась как тренажер для профилактики застойных заболеваний органов малого\r\nтаза. Сегодня — это необычный способ привнести в сексуальную жизнь новые нотки.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;По аналогии с мужским\r\nтренажером, женская помпа призвана увеличить приток крови к половым органам и\r\nповысить чувствительность. Пластиковая чаша прижимается к области вагины, с\r\nпомощью груши в ней создается вакуум. При проведении нескольких процедур\r\n«вакуум-воздух» большие и малые губы женщины, а также клитор значительно\r\nувеличиваются в размерах. Их чувствительность сильно повышается. Внешний вид\r\nженских половых органов после использования помпы многие мужчины считают более\r\nвозбуждающим.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Такой массаж имеет\r\nнесомненную пользу: при регулярном его проведении женщина становится более\r\nчувствительной, быстрее достигает оргазма. Оргазмы становятся ярче и\r\nпродолжительнее. Кроме того, можно купить помпы, которые оснащены встроенными\r\nвибраторами. Сочетание вакуумного массажа и воздействия вибратора дарит ни с чем\r\nнесравнимые сексуальные переживания.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Однако здесь стоит\r\nсоблюдать осторожность и не увеличивать время воздействия вакуума выше\r\nуказанного в инструкции. Злоупотребление помпой может привести к отеку,\r\nгиперемии и подкожным кровоизлияниям, в то время как умеренное использование\r\nпринесет только приятные эмоции, усилит возбуждение и сделает секс\r\nнезабываемым.&lt;/span&gt;&lt;span style=&quot;font-family: Tahoma, sans-serif; color: rgb(41, 45, 45);&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(144, 1, 'Презервативы', '&lt;p class=&quot;MsoNormal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;В наше время\r\nпрезервативы, это не только средство защиты от преждевременной беременности, но\r\nи возможность разнообразить свою интимную жизнь! Точечные, ребристые, с\r\nшариками, с усиками, ультратонкие, ароматизированные, с продлевающим эффектом,&amp;nbsp;&lt;span class=&quot;apple-converted-space&quot; style=&quot;&quot;&gt;&amp;nbsp;&lt;/span&gt;решать только тебе, что ты захочешь сегодня!&lt;/span&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;;color:black;mso-themecolor:text1&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;&lt;span style=&quot;font-size:14.0pt;line-height:115%&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(143, 2, 'qwertyu', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(137, 2, 'sdfgh', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(137, 1, 'Страпоны', '&lt;p style=&quot;margin: 0cm 0cm 0.0001pt; text-align: justify; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Страпоны и фаллопротезы представляют собой\r\nуникальную секс игрушку, состоящую из трусиков или ремешков и насадки\r\nфаллоимитатора. Однако по своей конструкции они делятся на мужские и женские. &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin: 0cm 0cm 0.0001pt; text-align: justify; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Мужские модели чаще всего называют фаллопротезами,\r\nтак как в большинстве из них предусмотрено отверстие для помещения полового\r\nоргана со слабой эрекцией. &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin: 0cm 0cm 0.0001pt; text-align: justify; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Женские модели помогут очаровательной\r\nпредставительнице женского пола испытать наслаждение от главенствующей роли в\r\nпаре. При этом ее партнером может быть как мужчина, так и другая женщина.\r\nНекоторые модели страпонов и фаллопротезов снабжены дополнительными насадками,\r\nнаправленными на стимуляцию клитора, влагалища и ануса самой партнерши. &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin: 0cm 0cm 0.0001pt; text-align: justify; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Существуют также мужские страпоны, которые позволяют\r\nосуществить потаенную мечту практически каждой женщины о двойном проникновении,\r\nне приглашая в постель посторонних. Эти интимные игрушки помогут приятно\r\nразнообразить и усовершенствовать интимную жизнь абсолютно любой паре.&amp;nbsp; &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin: 0cm 0cm 0.0001pt; text-align: justify; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&amp;nbsp;Стоит также\r\nотметить, что страпоны отличаются друг от друга размерами, формой, количеством\r\nнасадок и материалом, использованным при изготовлении. Благодаря этому\r\nмногообразию найти идеальный вариант и купить страпон по своему вкусу удастся\r\nабсолютно любой паре, вне зависимости от их половой принадлежности, возраста и\r\nстажа интимной жизни.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p style=&quot;margin: 0cm 0cm 0.0001pt; text-align: justify; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Помните, заботясь о качестве своей интимной жизни,\r\nвы сохраняете любовь!&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;span style=&quot;background-color: rgb(255, 255, 255); font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;text-align: justify;&quot;&gt;Ни одному партнеру или партнерше не придет в голову\r\nискать приключения на стороне, если их сексуальная жизнь разнообразна и полна\r\nвпечатлений!&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(150, 1, 'Игры для двоих|Сувениры', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(150, 2, 'asdf', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(73, 1, 'Духи|Pheromone', '&lt;h4&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;Феромоны – особые\r\nхимические вещества, которые выделяются железами и тканями живых организмов –\r\nживотными и человеком. Эти вещества имеют очень высокую степень «летучести»,\r\nпоэтому легко передаются с тела в воздух. Обоняние человека или животных\r\nулавливает феромоны в воздухе и посылает особые сигналы в мозг, но эти\r\nвещества, вместе с тем, не имеют абсолютно никакого запаха. Феромоны способны\r\nусиливать сексуальное желание, стимулировать влечение. Само слово «феромоны»\r\nпроизошло от греческого слова «феромон», что переводится дословно, как\r\n«влекущий гормон».&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;Духи с\r\nферомонами — это не панацея, которая поможет стать любимой и популярной. Это\r\nлишь аксессуар, который поможет подчеркнуть другие достоинства. Духи с\r\nферомонами можно расценивать, как флажок, который привлекает внимание. Но вот\r\nудержать его нужно с помощью других достоинств. Духи не гарантируют\r\nвлюбленность, они способны породить только заинтересованность и сексуальное\r\nвлечение.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-family: Arial;&quot;&gt;Духи\r\nсодержат в себе ароматы амбры и мускуса. В противном случае они не смогут\r\nостаться на коже, сочетаться с другим ароматом. Потому можно сказать, что в\r\nлюбом флакончике духов содержится некоторая часть феромонов. Именно поэтому они\r\nвызывали такое уважение и даже почтение со стороны женщин и мужчин даже в те\r\nвремена, когда науке ничего не было известно и феромонах и их волшебной силе.\r\nДухи с феромонами отличаются от обычных количеством тех самых волшебных\r\nхимических элементов, которые позволяют привлечь внимание представителей\r\nпротивоположного пола.&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;&lt;p&gt;\r\n\r\n\r\n\r\n&lt;/p&gt;', '', '', '', ''),
(73, 2, 'jhjjkplkjf', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(145, 2, 'asdfgh', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(145, 1, 'Клиторальные стимуляторы', '&lt;h4&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;font-size: 9pt; line-height: 115%;&quot;&gt;Клитор у женщины, так же, как и пенис у\r\nмужчины является одним из важнейших органов в сексуальной жизни. Так же, как и\r\nпенис клитор состоит из пещеристой ткани и является самой чувствительной\r\nэрогенной зоной. Этот орган набухает при возбуждении и предназначен\r\nисключительно для получения удовольствия.&amp;nbsp;&lt;/span&gt;&lt;span style=&quot;font-size: 9pt; line-height: 115%;&quot;&gt;Интересно то, что приток крови к половым органам женщины\r\nзначительно больший, чем приток крови к мужскому пенису. Однако эрекция заметна\r\nнамного меньше.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 9pt; line-height: 115%; font-family: Arial;&quot;&gt;Большинство женщин достигает оргазма именно стимуляцией\r\nклитора. Не менее важна стимуляция и непосредственно во время близости. Однако,\r\nк сожалению, во время полового акта этой области не всегда уделяется должное\r\nвнимание из-за затруднённой доступности этой эрогенной зоны для ласки руками.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;font-size: 9pt; line-height: 115%;&quot;&gt;Клиторальный стимулятор – мини-вибратор,\r\nпредназначенный для стимуляции клиторальной зоны. Клиторальные стимуляторы\r\nмогут быть с выносным или встроенным пультом управления. Изделие может обладать\r\nспециальными приспособлениями для закрепления его в области клитора (это могут\r\nбыть либо резиночки, либо специальные трусики).&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 9pt; line-height: 115%; font-family: Arial;&quot;&gt;Симпатичные гелевые или\r\nкиберскиновые зайчики, мишки, мотыльки и бабочки готовы затрепетать под\r\nвоздействием мини-помощников – маленьких вибраторов, встроенных в их нежные\r\nтельца, и подарить вам точечную вибрацию или пульсацию, сила и степень\r\nвоздействия которых полностью подвластны вашему желанию. Женщина может использовать\r\n«бабочку» как во время полового акта, так и для мастурбации.&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;\r\n\r\n\r\n\r\n', '', '', '', ''),
(265, 1, 'Ролевые костюмы', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(237, 1, 'Двойные|Безременные|Фаллопротезы', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(237, 2, 'double', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(70, 1, 'Вагинальные шарики|Тренировка интимных мышц', '&lt;h4 style=&quot;text-indent:-18.0pt;mso-list:l0 level1 lfo1&quot;&gt;&lt;span style=&quot;color: black; line-height: 115%; font-size: 11pt; font-family: Arial;&quot;&gt;Вагинальные шарики,\r\nсозданные для тренировки мышц, представляют собой две (реже более)\r\nпоследовательно связанные сферы, изготовленные из латекса, резины, пластика и\r\nдаже металла или древесины. Внутри оргазменных мячиков подвешены железные\r\nгрузики, колеблющиеся при малейшем движении. В нашем магазине присутствуют\r\nшарики со смещенным центром тяжести, утяжеленные, совершенно гладкие или с\r\nэффектом шершавости. Кроме этого, для тренировки влагалищных мышц можно\r\nиспользовать яйцеобразные аксессуары этого типа, которые используются\r\nпоодиночке, а не связанными парами, имеют большие размеры, чем стандартные\r\nвагинальные сферы, и часто оснащаются эффектом вибрации. Последний помогает получить\r\nмаксимальное удовлетворение от процесса применения, и усиливает позитивный\r\nрезультат от тренировки.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;color: black; font-family: Arial;&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/h4&gt;&lt;h4 style=&quot;text-indent:-18.0pt;mso-list:l0 level1 lfo1&quot;&gt;&lt;span style=&quot;color: black; font-family: Arial;&quot;&gt;Вы должны научится слушать ваше тело, ощущать каждую\r\nклеточку. Мы предлагаем Вам примерные упражнения с вагинальными шариками,\r\nкаждое упражнение выполняйте 5-7 раз:&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;1.&lt;span style=&quot;font-variant-numeric: normal; font-stretch: normal; font-size: 7pt; line-height: normal;&quot;&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;!--[endif]--&gt;&lt;span style=&quot;color: black;&quot;&gt;Прежде,\r\nчем ввести первый вагинальный шарик, смажьте его увлажняющей смазкой или\r\nспециальным гелем( &lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;color: black;&quot;&gt;Intim&lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;color: black;&quot;&gt; &lt;/span&gt;&lt;span lang=&quot;EN-US&quot; style=&quot;color: black;&quot;&gt;Fitness&lt;/span&gt;&lt;span style=&quot;color: black;&quot;&gt;).\r\nПосле этого погрузите шарики(шарик) во влагалище как можно дальше, и постарайтесь\r\nощутить их внутри себя.&lt;br&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;2.&lt;span style=&quot;font-variant-numeric: normal; font-stretch: normal; font-size: 7pt; line-height: normal;&quot;&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: black;&quot;&gt;Встаньте\r\nпрямо, ноги на ширине плеч, колени слегка согнуты. Начните вращать таз по\r\nкругу. При&amp;nbsp; движении вперед делайте вдох\r\nи сжимайте вагинальные мышцы, при движении назад – выдох и расслабляйте мышцы.\r\nПри этом верхний плечевой пояс должен быть расслаблен и неподвижен, а Ваши\r\nстопы не должны отрываться от пола. Затем поменяйте направление движения.&lt;br&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;3.&lt;span style=&quot;font-variant-numeric: normal; font-stretch: normal; font-size: 7pt; line-height: normal;&quot;&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: black;&quot;&gt;Встаньте\r\nпрямо, ноги на ширине плеч. Поочередно делайте круговые движения правой и левой\r\nполовинами таза, рисуя восьмерку в плоскости вперед-назад. Сделайте упражнения\r\nв обоих направлениях.&lt;br&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;4.&lt;span style=&quot;font-variant-numeric: normal; font-stretch: normal; font-size: 7pt; line-height: normal;&quot;&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: black;&quot;&gt;Встаньте\r\nпрямо, ноги на ширине плеч. В первой фазе движения на вдохе максимально\r\nтолкните таз вперед, руки отведите назад, задержите дыхание на несколько\r\nсекунд. Затем на выдохе отклоните максимально таз назад, руки вытяните вперед,\r\nрасслабьтесь.&lt;br&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;5.&lt;span style=&quot;font-variant-numeric: normal; font-stretch: normal; font-size: 7pt; line-height: normal;&quot;&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;!--[endif]--&gt;&lt;span style=&quot;color: black;&quot;&gt;Лягте\r\nна спину, согните ноги в коленях, ступни поставьте на пол на ширине таза,\r\nколени не соприкасаются. На вдохе поднимите таз вверх, поджав копчик вперед\r\n(шарик поднимается вверх). Затем задержите дыхание на несколько секунд. На\r\nвыдохе опустите таз на пол, сохранив прогиб в пояснице(шарик опустится вниз).&lt;br&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;6.&lt;span style=&quot;font-variant-numeric: normal; font-stretch: normal; font-size: 7pt; line-height: normal;&quot;&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: black;&quot;&gt;В\r\nположении лежа на спине, ноги вместе, руки вдоль туловища, ладони соприкасаются\r\nс полом, начните перекатывать таз из стороны в сторону, не отрывая от пола\r\nладони, ступни и голову. Вдох сопровождается поворотом в одну сторону, а выдох\r\nв другую.&lt;br&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;7.&lt;span style=&quot;font-variant-numeric: normal; font-stretch: normal; font-size: 7pt; line-height: normal;&quot;&gt;&amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp; &amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: black;&quot;&gt;Встаньте\r\nпрямо,&amp;nbsp; ноги на ширине плеч. Потяните\r\nнемного петельку от шариков вниз, как будто хотите их извлечь, в этот момент\r\nсожмите мышцы очень сильно, что не допустить выпадения шарика( удерживайте его\r\nвнутри влагалища), затем мышцами попытайтесь немного втянуть шарики во\r\nвлагалище очень глубоко, и опять повторяя предыдущие манипуляции. Также можете\r\nпопробовать вытолкнуть шарики мышцами.&lt;br&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: black;&quot;&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;Выполняя эти упражнения ежедневно, через\r\nнеделю Вы будете чувствовать шарик внутри, появится ощущение внутренних мышц. А\r\nчерез 3-4 недели регулярных занятий сможете легко управлять шариком и не только…&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;&lt;p class=&quot;MsoNormal&quot;&gt;\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n&lt;/p&gt;&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(270, 1, 'Боди|Комплекты белья', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(293, 1, 'Без вибрации', '&lt;h4 style=&quot;line-height: 1.4; color: rgb(102, 102, 102); background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; text-align: justify;&quot;&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: rgb(13, 13, 13);&quot;&gt;&lt;span style=&quot;text-decoration-line: underline;&quot;&gt;Анальные пробки&lt;/span&gt;&amp;nbsp;могут иметь основания с липучками и даже со стразами, которые придают им эстетичности.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;color: rgb(13, 13, 13);&quot;&gt;Эти изделия могут использоваться не только для тренировок. Они подойдут и для самоудовлетворения, и для усиления ощущений во время полового акта. Так женщина может ввести себе пробку в анальное отверстие. Это сделает ее влагалище более узким. Поэтому ощущения от секса у обоих партнеров будут более яркими, чем обычно.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;color: rgb(13, 13, 13);&quot;&gt;При этом не стоит думать, что данное изделие подходит исключительно женщинам. В профилактических целях и для особого вида удовольствия его могут использовать и мужчины.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;color: rgb(13, 13, 13);&quot;&gt;Чтобы испытать яркие ощущения от секса, сначала необходимо подобрать изделие правильных размеров и формы.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;color: rgb(13, 13, 13);&quot;&gt;Также нужно помнить, что анус не выделяет какую-либо смазку. Поэтому для введения в него пробки и для анального секса необходимо использовать искусственные смазки и лубриканты. Для тех, кто только начинает постигать прелести подобных половых актов подойдет смазка с обезболивающим эффектом.&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;', '', '', '', ''),
(186, 1, 'Для точки G', '&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Где же она точка G? По своей физиалогии мужской член с трудом может нащупать её. Вибраторы специальной формы помогут Вам с поисками. Немного загнутый кончик этих вибромассажеров очень нежно простимулируют все вагинальные мышцы и конечно помогут Вам побывать на седьмом небе от удовольствия.&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(265, 2, 'wedfrgthyjuikol', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(266, 1, 'Сетка', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(182, 1, 'Mini', '&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Отличный интимный аксессуар, который можно взять с собой!&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Необычная форма, посторонние никогда не догадаются, что это, если Вы сами не захотите показать его в применении! &lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Подходит как для анальных ласк, так и для стимуляции всех эрогенных зон!&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(294, 1, 'С вибрацией', '&lt;h4 style=&quot;font-family: &amp;quot;Open Sans&amp;quot;, sans-serif; color: rgb(102, 102, 102);&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;Анальные стимуляторы фантазийной формы доставят Вам незабываемые ощущения!&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;Никто и никогда не догадается что это, если Вы сами не заходите показать игрушку в применении!&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;Отлично подходят как женщинам, так и мужчинам!&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;А функция вибрации, вознесет Вам на седьмое небо удовольствий!&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;', '', '', '', ''),
(68, 1, 'Анальные игрушки', '&lt;p&gt;&lt;font color=&quot;#000000&quot; face=&quot;Times New Roman&quot; size=&quot;3&quot;&gt;\r\n\r\n&lt;/font&gt;&lt;/p&gt;&lt;h4 style=&quot;text-align: justify; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; line-height: 1.4;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;background-image: initial; background-attachment: initial; background-size: initial; background-origin: initial; background-clip: initial; background-position: initial; background-repeat: initial;&quot;&gt;Анальные стимуляторы,\r\nвыполняемые из мягкого латекса, силикона или киберкожи, могут иметь различный\r\nдиаметр, способствуя постепенной разработки мышечных стенок ануса. Обтекаемость\r\nформу предусматривает безболезненное введение анального стимулятора\r\nнепосредственно в анус.&lt;br&gt;&lt;/span&gt;Анальный секс является довольно щепетильной темой для\r\nдевушек. Женщины побаиваются его. На самом деле в процессе такого секса у\r\nдевушек часто возникают неприятные и болевые ощущения. Но это можно исправить.\r\nАнальный секс может приносить наслаждение, если к нему правильно подготовиться.\r\nДля этого необходимо делать определенные упражнения. А в этом помогут анальные\r\nпробки.&lt;br&gt;Еще одним преимуществом подобного\r\nприспособления, является предварительный ввод анального стимулятора в анус, при\r\nжелании заняться анальным сексом, так как он способствует правильной подготовке\r\nи расслаблению, во избежание неприятных и даже болезненных ощущений.\r\nДанная пробка является узкой у начала и более широкой у основания, которое\r\nпредотвращает проваливание данного изделия в анальное отверстие. Формы и\r\nразмеры этих интимных игрушек могут быть разными. Выбирать их стоит в\r\nсоответствии с собственными предпочтениями.&lt;br&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Анальные пробки&lt;/span&gt; могут иметь основания с липучками и\r\nдаже со стразами, которые придают им эстетичности.&lt;br&gt;Эти изделия могут использоваться не только для\r\nтренировок. Они подойдут и для самоудовлетворения, и для усиления ощущений во\r\nвремя полового акта. Так женщина может ввести себе пробку в анальное отверстие.\r\nЭто сделает ее влагалище более узким. Поэтому ощущения от секса у обоих\r\nпартнеров будут более яркими, чем обычно.&lt;br&gt;При этом не стоит думать, что данное изделие подходит\r\nисключительно женщинам. В профилактических целях и для особого вида удовольствия его могут использовать и\r\nмужчины.&lt;br&gt;Чтобы испытать яркие ощущения от секса, сначала\r\nнеобходимо подобрать изделие правильных размеров и формы.&lt;br&gt;Также нужно помнить, что анус не выделяет какую-либо\r\nсмазку. Поэтому для введения в него пробки и для анального секса необходимо\r\nиспользовать искусственные смазки и лубриканты. Для тех, кто только начинает\r\nпостигать прелести подобных половых актов подойдет смазка с обезболивающим\r\nэффектом.&lt;br&gt;&lt;span style=&quot;font-size: 11pt;&quot;&gt;Еще одна более популярная сексуальная игрушка &amp;nbsp;– анальная цепочка или бусы.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 11pt;&quot;&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Тайские бусы&lt;/span&gt; – так еще называют &lt;span style=&quot;text-decoration: underline;&quot;&gt;анальную цепочку&lt;/span&gt; – могут служить\r\nисточником дополнительного сексуального удовольствия или средством для\r\nдостижения оргазма. Такая игрушка одинаково хорошо подойдет и для искушенных\r\nанальными ласками любовников, и для тех, кто только пускается в исследования.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 11pt;&quot;&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Анальная цепочка&lt;/span&gt; может применяться не только в качестве стимулятора, но и\r\nкак подготовка к анальному сексу, чтобы растянуть и расслабить мышцы сфинктера.\r\nВ таком случае следует обратить внимание на модели с шариками разного диаметра\r\nна одной цепочке. Также интересной будет цепочка с дополнительной\r\nвибростимуляцией.&lt;/span&gt;&lt;/span&gt;&lt;/h4&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;line-height: 1.4;&quot;&gt;\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n&lt;/p&gt;', '', '', '', ''),
(68, 2, 'fdgdfh', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(138, 2, 'asdfgh', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(144, 2, 'zxcvb', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(136, 1, 'Фаллоимитаторы|Дилдо', '&lt;p&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&lt;em style=&quot;&quot;&gt;&lt;span style=&quot;font-size: 12pt; line-height: 115%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-style: normal;&quot;&gt;Фаллоимитатор&lt;/span&gt;&lt;/em&gt;&lt;span class=&quot;apple-converted-space&quot; style=&quot;&quot;&gt;&lt;i&gt;&lt;span style=&quot;font-size: 12pt; line-height: 115%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/i&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 12pt; line-height: 115%; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;– это аналог полового члена. Он может точно повторять вид пениса, а\r\nможет лишь отдаленно напоминать его. Вне зависимости от сложности изделия, все\r\nимитаторы исполняют роль своеобразных тренажеров, манипуляции с которыми\r\nпозволяют изучить собственные сексуальные реакции, реализовать фантазии,\r\nиспользовать их в сексуальных играх с партнером как для вагинального, так и для\r\nанального секса. &lt;/span&gt;&lt;span style=&quot;font-size: 12pt; line-height: 115%;&quot;&gt;Фаллоимитаторы из различных\r\nматериалов, это силикон и латекс, акрил и пластик, дерево и металл, камень и\r\nстекло. Самые распространенные фаллоимитаторы выполненные из силикона, самые\r\nреалистичные — из латекса. Следует выделить двойной фаллоимитатор, который\r\nспособен доставить женщине несравнимое удовольствие, осуществляя двойное\r\nпроникновение.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;\r\n\r\n&lt;p class=&quot;MsoNormal&quot; style=&quot;mso-margin-top-alt:auto;mso-margin-bottom-alt:auto;\r\nline-height:normal&quot;&gt;&lt;span class=&quot;apple-converted-space&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Конечно, фаллоимитатор, какой бы он\r\nни был, - это всего лишь игрушка, и он никогда не вытеснит теплых человеческих\r\nвзаимоотношений, но помочь решить многие сексуальные проблемы он может. Поэтому\r\nне стоит себе отказывать в том, что укрепит или наладит когда-то возникшую\r\nсвязь между двумя людьми. Ведь все это придумано во имя любви.&lt;/span&gt;&lt;span style=&quot;font-family: Arial, sans-serif;&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(136, 2, 'asdfgh', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(308, 1, 'SEX косметика', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(308, 2, 'sdfghjk;lkjhbg', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(69, 1, 'БДСМ|FETISH', '&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom: 6.4pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Фетишизм - разновидность сексуального&amp;nbsp;поведения,\r\nпри которой источником и стимулом для полового влечения&amp;nbsp;становятся\r\nнеодушевлённые предметы: одежда, обувь, вещи, сделанные из определённого\r\nматериала.&amp;nbsp;Фетиш - чувственная сторона секса, без совокупления. У каждого\r\nсвой фетиш, кто-то сходит с ума от женских ножек, кто-то от кожи и латекса.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom: 6.4pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;БДСМ – это\r\nпсихосексуальная субкультура, которая базируется на обмене эротической властью\r\nи других формах половых отношений, затрагивающих господство, подчинение и\r\nролевые игры. Аббревиатура появилась на свет в начале 90-х годов прошлого\r\nстолетия – тогда, когда бондаж/дисциплина (BD) и сексуальное доминирование (DS)\r\nсчиталось подразделением садомазохизма (SM). В нашем случае BDSM – это\r\nполноценный мир эротических аксессуаров и игрушек, которые позволяют на\r\nпрактике прочувствовать вкус сексуальных игр, доминирования и подчинения в\r\nпостели.&amp;nbsp;&lt;br&gt;\r\nЭротический фетиш (фетишизм) – это один из видов сексуального поведения людей,\r\nкогда основным источником возбуждения становятся неодушевленные предметы, а\r\nименно, нижнее белье, обувь, вещи из определенного материала.&amp;nbsp;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom: 0.0001pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Много людей практикуют БДСМ: плети и наручники продаются у нас в интернет\r\nмагазине каждый день, правда, кто-то берёт ради шутки, а другие выбирают плеть\r\nсерьёзно: чтоб сильно била или наоборот, не оставляла следов.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom: 0.0001pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Понять таких людей не сложно: они просто выплёскивают свою энергию во время\r\nтаких игр или дают о себе знать корни из далёкого детства. Женщина, любящая\r\nбыть в роли &quot;госпожи&quot; испытывает положительные эмоции от осознания\r\nсвоего превосходства, а &quot;избиваемый&quot; чувствует всплеск адреналина,\r\nиспытывает &quot;встряску&quot;.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom: 6.4pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Попробуйте купить\r\nплетки, наручники, кляпы, которые помогут вам воплотить в жизнь самые разные\r\nигры, например, «Госпожа и ее раб» или «Господин и его наложница». Вариантов\r\nможет быть масса! Кто знает, быть может, заглянув за рамки привычных занятий\r\nлюбовью, вы найдете именно то, что искали так давно: экстрим на грани,\r\nадреналин и фантастические эмоции!&amp;nbsp;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;span style=&quot;font-size: 11pt; line-height: 115%; color: black;&quot;&gt;\r\n&lt;!--[if !supportLineBreakNewLine]--&gt;&lt;br&gt;\r\n&lt;!--[endif]--&gt;&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(69, 2, 'sdgfhmj', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(78, 1, 'Выгодная цена!', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(78, 2, 'fgdfg', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(313, 1, 'Жидкий вибратор', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(313, 2, 'sdfghj;lkjhg', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', '');
INSERT INTO `oc_category_description` (`category_id`, `language_id`, `name`, `description`, `meta_title`, `meta_h1`, `meta_description`, `meta_keyword`) VALUES
(148, 1, 'Вагины|Мастурбаторы|Куклы', '&lt;h4&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Получать сексуальную разрядку очень важно для мужского здоровья, но\r\nрегулярный секс не всегда возможен. Помочь в таком случаем может мастурбация, а\r\nкупив в секс шопе искусственную вагину или мастурбатор, можно достичь\r\nмаксимально реальных ощущений. Можно выбрать мастурбатор в виде ротика, вагины\r\nили ануса, разных цветов и из разнообразных материалов, с вибрацией для\r\nдополнительной стимуляции и без нее.&lt;/span&gt;&lt;/span&gt;&lt;table class=&quot;MsoNormalTable&quot; border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; width=&quot;100%&quot; style=&quot;width: 100%; background: white;&quot;&gt;\r\n &lt;tbody&gt;&lt;tr&gt;\r\n  &lt;td valign=&quot;top&quot; style=&quot;padding:0cm 0cm 0cm 0cm&quot;&gt;\r\n  &lt;table class=&quot;MsoNormalTable&quot; border=&quot;0&quot; cellspacing=&quot;0&quot; cellpadding=&quot;0&quot; width=&quot;100%&quot; style=&quot;width: 100%;&quot;&gt;\r\n   &lt;tbody&gt;&lt;tr&gt;\r\n    &lt;td width=&quot;0&quot; valign=&quot;top&quot; style=&quot;width:.3pt;padding:0cm 22.5pt 0cm 0cm&quot;&gt;\r\n    &lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom:0cm;margin-bottom:.0001pt;\r\n    line-height:14.25pt&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Имитаторы женских половых органов отличаются формой, материалом,&amp;nbsp; (чаще всего это латекс, силикон,\r\n    киберсиликон и другие подобные материалы), наличием вибратора. &lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n    &lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom:0cm;margin-bottom:.0001pt;\r\n    line-height:14.25pt&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;По всей внутренней длине вагины, часто располагаются всевозможные мягкие\r\n    шишечки-возбудители. Они оказывают активное массажное воздействие на пенис\r\n    во время использования вагины. Кроме того, массажный эффект достигается\r\n    благодаря вибрации (при наличии специального устройства). Вне зависимости\r\n    от модели, вагина плотно обхватывает половой член. Благодаря этому у\r\n    мужчины возникают ощущения, подобные тем, что возникают при близости с\r\n    молоденькой девушкой.&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom:0cm;margin-bottom:.0001pt;\r\n    line-height:14.25pt&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin-bottom: 10px; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;Заказать реалистичную надувную секс куклу для мужчин осмелится не каждый. Очень часто такую секс-игрушку преподносят в подарок мужчине «без комплексов». Однако если вы сами решитесь на подобное приобретение – поверьте, вы не останетесь разочарованы.&amp;nbsp;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p style=&quot;margin-bottom: 10px; color: rgb(0, 0, 0);&quot;&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;При постоянном или временном отсутствии сексуального партнера можно использовать эротические куклы для секса, которые точно воспроизводят тело человека. Рост таких кукол составляет от полутора метров с точной или приблизительной имитацией половых органов. Надувные девушки помогают преодолевать комплексы, которые проявляются у некоторых людей в интимной жизни с партнером, получая при этом сексуальную разрядку. В некоторых моделях предусмотрено использование вибратора, что доставит еще большее удовольствие!&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom:0cm;margin-bottom:.0001pt;\r\n    line-height:14.25pt&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;\r\n    &lt;/td&gt;\r\n   &lt;/tr&gt;\r\n  &lt;/tbody&gt;&lt;/table&gt;\r\n  &lt;/td&gt;\r\n &lt;/tr&gt;\r\n&lt;/tbody&gt;&lt;/table&gt;&lt;/h4&gt;\r\n\r\n', '', '', '', ''),
(148, 2, 'wsdf', '&lt;p&gt;&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(95, 1, 'Интимные зажимы и украшения', '&lt;h4 style=&quot;margin-bottom: 6.4pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;Половые губы – невероятно притягательны для мужчин. Например, такое\r\nстроение тела девушки, когда малые половые губы выступают из-за больших, многие\r\nпоэты эротического жанра называли бутоном розы, а сами губы сравнивали с\r\nлепестками.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;Во время прелюдии, интимные украшения половых губ привлекут дополнительный\r\nинтерес, возбудят и разогреют партнера. Самое распространенное бдсм украшение –\r\nклипсы или зажимы на малые половые губы. Они делаются из металла, возможно с\r\nимитацией под золото или серебро. Зачастую украшены стразами, бусинами или\r\nкристаллами.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;Одеваются они предельно просто, просто раздвинув кончики в разные стороны,\r\nклипсы одеваются на клитор и малые половые губы. Особенная прелесть таких\r\nукрашений в том, что за счет некоторого перекрытия кровотока, губы и клитор\r\nстановятся немного больше в размерах, как будто их обладательница возбуждена и\r\nхочет секса.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;Банально было бы\r\nговорить о том, что женская грудь является одной из самых чувствительных\r\nэрогенных зон. Однако факт остается фактом и нельзя оставлять без внимания эту\r\nнежную и &amp;nbsp;чуткую часть женского тела. Благодаря стремительному развитию\r\nсекс индустрии и тому, что люди становятся более раскрепощенными в сексуальных\r\nотношениях, меняется восприятие ко многим секс-игрушкам и всему, что с ними\r\nсвязано.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;Для начинающих подойдут\r\nрегулируемые зажимы на соски, в которых сила давления устанавливается\r\nспециальным винтиком. Такие модели чаще всего выполняются с использованием\r\nлатекса для более комфортного ношения. Так называемые зажимы «аллигаторы»\r\nнаиболее удобны и безопасны, поэтому подойдут девушкам с очень чувствительными\r\nсосками.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;Зажимы на соски с\r\nвибрацией часто имеют форму «крокодила», но на конце оснащены вибрирующим\r\nэлементом, который в сумме способен доставить ни с чем несравнимые ощущения,\r\nудерживая возбуждение максимально долго. Самыми нежными считаются специальные\r\nвибростимулирующие присоски, которые не доставляют дискомфорт, а просто ласково\r\nмассируют соски.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family: Arial;&quot;&gt;&lt;span style=&quot;color: black;&quot;&gt;\r\nКроме того, что все модели выполняют свое целевое назначение, они еще и являются\r\nзамечательным дополнительным аксессуаром. К примеру, зажимы с цепочкой не\r\nтолько доставляют приятные возбуждающие ощущения за счет того, что цепь\r\nкасается тела, но и выглядят очень эстетично.&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;color: black; font-family: Arial;&quot;&gt;&amp;nbsp;Для того чтобы\r\nправильно использовать зажимы для сосков, нужно понимать физиологию - Как у\r\nженщин так и у мужчин, соски представляют собой сверх чувствительные центры,\r\nсодержащие миллионы, а то и миллиарды нервных окончаний, поэтому сдавливание их\r\nво время возбужденного состояния, временно останавливает приток крови, и именно\r\nэто вызывает ощущение &quot;возбуждающей&quot; боли. Поэтому, если вы желаете\r\nдоставить вашему партнеру или себе максимальное удовольствие, сначала хорошо\r\nвозбудите соски, когда они станут твердыми, оденьте зажимы, и продолжайте\r\nласкать грудь и интимные зоны всего тела, тогда возбуждение будет нарастать и\r\nсекс будет незабываемым, а экстаз просто фантастичный.&lt;/span&gt;&lt;/h4&gt;&lt;p style=&quot;margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n&lt;/p&gt;&lt;p style=&quot;margin: 0cm 0cm 0.0001pt; line-height: 15pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-size:11.0pt;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;;color:black;\r\nmso-themecolor:text1&quot;&gt;&lt;o:p&gt;&lt;br&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(97, 1, 'Кляпы', '&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom: 0.0001pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial, sans-serif; color: rgb(0, 0, 0);&quot;&gt;БДСМ-кляп&amp;nbsp;—\r\nнеотъемлемый атрибут для большинства техник бондажа. С его помощью можно лишить\r\nпартнера возможности издавать членораздельные звуки, тем самым придав ему образ\r\nжертвы. Это приспособление могут использовать не только подчиняющие, но и\r\nподчиняющиеся участники эротической ролевой игры.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom: 0.0001pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family: Arial, sans-serif; color: rgb(0, 0, 0);&quot;&gt;Среди них\r\nособой популярностью пользуются шариковые. Такие&amp;nbsp;кляпы&amp;nbsp;используются в\r\nпрактике&amp;nbsp;БДСМ&amp;nbsp;гораздо чаще, чем другие виды таких аксессуаров.\r\nГлавные причины такой популярности — это дешевизна, удобство и практичность\r\nэтих приспособлений. Шариковый&amp;nbsp;кляп&amp;nbsp;можно закрепить&amp;nbsp;во\r\nрту&amp;nbsp;участника&amp;nbsp;БДСМ-сессии при помощи специальных ремней и быстро снять\r\nего в случае, если партнер испытывает сильный дискомфорт.&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;p3&quot; style=&quot;margin: 0cm 0cm 0.0001pt; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;\r\n\r\n\r\n\r\n&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot; style=&quot;margin-bottom: 6.4pt; line-height: normal; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial;&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Arial&amp;quot;,&amp;quot;sans-serif&amp;quot;;mso-fareast-font-family:\r\n&amp;quot;Times New Roman&amp;quot;;mso-fareast-language:RU&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;Не менее популярны кляпы-кольцо,\r\nспециально созданные для того, чтобы ваш партнер не смог закрыть свой ротик в\r\nсамый ответственный момент!&lt;/span&gt;&lt;o:p&gt;&lt;/o:p&gt;&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(103, 2, 'dfg ldfh dfh sj  sj lsjl gsl ', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(104, 1, 'Маски', '&lt;p style=&quot;box-sizing: inherit; margin-bottom: 0px; padding: 15px 0px 0px; color: rgb(51, 51, 51); font-family: Arial, Helvetica, sans-serif;&quot;&gt;Скучная интимная жизнь – это не дело. Если вам кажется, что в вашей спальне в последнее время что-то пошло не так, берите ситуацию в свои руки! Кожаные маски, очки, повязки на глаза привнесут в интимную жизнь новые нотки, откроют вам яркие горизонты – стоит только захотеть... Попробуйте что-нибудь эдакое – и вы навсегда измените свое отношение к сексу. В лучшую сторону, разумеется.&amp;nbsp;&lt;/p&gt;&lt;p style=&quot;box-sizing: inherit; margin-bottom: 0px; padding: 15px 0px 0px; color: rgb(51, 51, 51); font-family: Arial, Helvetica, sans-serif;&quot;&gt;Аксессуары для «жестких» игр, легкого полового доминирования, ролевых перевоплощений в формате садо-мазо сегодня в фаворите – благодаря ним милая скромница в два счета превращается в роковую госпожу, дерзкая стерва в рабыню, обычный мужчина в строгого господина, а мачо-самец в покорного слугу или даже девушку. Не стоит менять жизнь радикально – а вот на час-другой немного пересмотреть свои привычные роли можно вполне.&amp;nbsp;&lt;/p&gt;', '', '', '', ''),
(105, 2, 'gdhk hfdgh sdfkjh dfk  dsfkdf kg  kg', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(264, 2, 'sdfrtgyui', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(264, 1, 'Бельё|Аксессуары', '&lt;p class=&quot;MsoNormal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Белье - это душа женщины, оно отражает ее мысли и настроения. Оно обладает притягательной силой, неподвластной времени. Женское белье вызывало восхищение всегда и везде, во все времена и у всех народов. Оно много говорит о женщине, которая его носит, и мужчины стараются всматриваться в него как можно внимательнее.&lt;/span&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;Уже давно белье перестало выполнять исключительно практическую, гигиеническую функцию – ее основной задачей стало подчеркнуть сексуальную привлекательность женщины.&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;/p&gt;&lt;p class=&quot;MsoNormal&quot;&gt;&lt;span style=&quot;font-family: Arial; color: rgb(0, 0, 0);&quot;&gt;&amp;nbsp;Женщине при этом недостаточно, чтобы ее сексуальность была признана противоположным полом, гораздо важнее, чтобы сама женщина чувствовала себя королевой. Несомненно оценивая при выборе нижнее белье с той точки зрения насколько оно понравится любимому мужчине, в большей степени женщина выбирает белье для себя – ей важно самой чувствовать себя в нем великолепной, неотразимой, сексуальной.&lt;/span&gt;&lt;/p&gt;', '', '', '', ''),
(293, 2, 'dfghjk', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', ''),
(63, 2, 'fdghfh', '&lt;p&gt;&lt;br&gt;&lt;/p&gt;', '', '', '', '');
